function dump(n, depth) {
  const info = {
    id: n.id, name: n.name, type: n.type,
    x: Math.round(n.x), y: Math.round(n.y), w: Math.round(n.width), h: Math.round(n.height),
  };
  if (n.type === "TEXT") info.characters = n.characters;
  if ("fills" in n && Array.isArray(n.fills)) info.fills = n.fills.map(f => ({type: f.type, color: f.color, visible: f.visible}));
  if ("cornerRadius" in n) info.radius = n.cornerRadius;
  if ("layoutMode" in n) info.layoutMode = n.layoutMode;
  if ("children" in n && depth > 0) info.children = n.children.map(c => dump(c, depth - 1));
  return info;
}
