// recolor helper: set fills on all descendant paint nodes of a node
function recolor(node, color){
  const paints = node.findAll(n => n.type==="VECTOR"||n.type==="RECTANGLE"||n.type==="ELLIPSE"||n.type==="POLYGON"||n.type==="STAR"||n.type==="TEXT");
  for (const p of paints) {
    // keep vector strokes if fills empty
    if (Array.isArray(p.fills) && p.fills.length) p.fills = [S(color)];
    if (p.strokes && p.strokes.length) p.strokes = [S(color)];
  }
}
