async function tabBarInstance(activeLabel){
  const inst = tabBarComp.createInstance();
  for (const it of inst.children) {
    const label = it.name.replace("Tab/","");
    const active = label === activeLabel;
    const ic = it.children[0]; const lt = it.children[1];
    const paintNodes = ic.findAll(n => n.type==="VECTOR"||n.type==="RECTANGLE"||n.type==="ELLIPSE");
    const col = active ? BRAND : GRAY;
    for (const p of paintNodes){ if (Array.isArray(p.fills)&&p.fills.length) p.fills=[S(col)]; if (p.strokes&&p.strokes.length) p.strokes=[S(col)]; }
    lt.fills = [S(active ? BRAND : GRAY)];
    lt.fontName = {family:"Inter", style: active ? "Semi Bold" : "Medium"};
  }
  return inst;
}

