function iconInst(name, w){
  const c = figma.getNodeById(ICONS[name]);
  const inst = c.createInstance();
  inst.resize(w, inst.height * (w/inst.width));
  return inst;
}
async function text(parent, chars, font, size, color, x, y, w){
  const t = figma.createText();
  parent.appendChild(t);
  t.fontName = {family:"Inter", style:font};
  t.characters = chars; t.fontSize = size; t.fills = [S(color)];
  t.x = x; t.y = y;
  if (w){ t.resize(w, t.height); t.textAutoResize = "HEIGHT"; }
  return t;
}

